import java.util.Scanner;

public class Main {
    static final int MAXN = 600;
    static long mod;
    static class Number {
        long val;
        Number() { val = 0; }
        Number(long v) {
            val = v % mod;
            if (val < 0) val += mod;
        }
        Number add(Number b) {
            return new Number((this.val + b.val) % mod);
        }
        Number subtract(Number b) {
            return new Number((this.val - b.val + mod) % mod);
        }
        Number multiply(Number b) {
            return new Number((this.val * b.val) % mod);
        }
        Number pow(long e) {
            Number res = new Number(1);
            Number base = new Number(this.val);
            while (e > 0) {
                if ((e & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                e >>= 1;
            }
            return res;
        }
        Number inv() {
            return this.pow(mod - 2);
        }
    }

    static Number[][] comb = new Number[MAXN][MAXN];
    static Number[] a = new Number[MAXN], c = new Number[MAXN];
    static Number[][][] dp = new Number[MAXN][MAXN][2], dpc = new Number[MAXN][MAXN][2];

    static long sumRange(long l, long r) {
        if (l > r) return 0;
        return (l + r) * (r - l + 1) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextLong();

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i) {
                    comb[i][j] = new Number(1);
                } else {
                    comb[i][j] = comb[i - 1][j - 1].add(comb[i - 1][j]);
                }
            }
        }

        a[0] = new Number(0);
        c[0] = new Number(1);
        a[1] = new Number(0);
        c[1] = new Number(2);

        for (int i = 2; i <= m; i++) {
            Number tmp = new Number(0);
            Number tmpc = new Number(0);
            for (int l = 0; l <= i; l++) {
                int r = i - 1 - l;
                long sumRangeL = sumRange(1, l);
                long sumRangeR = sumRange(1, r);
                Number term1 = c[l].multiply(c[r]).multiply(new Number(sumRangeL + sumRangeR))
                        .multiply(comb[i - 1][l]);
                Number term2 = (a[l].multiply(c[r]).add(a[r].multiply(c[l]))).multiply(comb[i - 1][l]).multiply(new Number(i + 1));
                tmp = tmp.add(term1).add(term2);
                tmpc = tmpc.add(c[l].multiply(c[r]).multiply(new Number(i + 1)).multiply(comb[i - 1][l]));
            }
            a[i] = tmp;
            c[i] = tmpc;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k < 2; k++) {
                    dpc[i][j][k] = new Number(0);
                }
            }
        }
        dpc[0][0][0] = new Number(1);

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j > i) continue;
                dpc[i][j][0] = dpc[i - 1][j][0].add(dpc[i - 1][j][1]);
                for (int k = 1; k <= j; k++) {
                    dpc[i][j][1] = dpc[i][j][1].add(c[k].multiply(comb[j][k]).multiply(dpc[i - k][j - k][0]));
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j > i) continue;
                dp[i][j][0] = dp[i - 1][j][0].add(dp[i - 1][j][1]);
                for (int k = 1; k <= j; k++) {
                    Number term1 = a[k].multiply(comb[j][k]).multiply(dpc[i - k][j - k][0]);
                    Number term2 = dp[i - k][j - k][0].multiply(c[k]).multiply(comb[j][k]);
                    dp[i][j][1] = dp[i][j][1].add(term1).add(term2);
                }
            }
        }

        Number result = dp[n][m][0].add(dp[n][m][1]);
        System.out.println(result.val);
        sc.close();
    }
}
